// Shared RIGGING.md reader for the derived checks. Values only, parsed by heading.
import { readFileSync } from 'node:fs';
import path from 'node:path';

export const ROOT = path.resolve(new URL('..', import.meta.url).pathname);

export function readRigging() {
  const text = readFileSync(path.join(ROOT, 'RIGGING.md'), 'utf8');
  const sections = {};
  let current = null;
  for (const line of text.split('\n')) {
    const heading = line.match(/^##\s+(.+?)\s*$/);
    if (heading) {
      current = heading[1];
      sections[current] = [];
      continue;
    }
    const item = line.match(/^-\s+([A-Za-z-]+):\s*(.*)$/);
    if (item && current) sections[current].push([item[1], item[2].trim()]);
  }
  return sections;
}

export function values(sections, heading, key) {
  return (sections[heading] || [])
    .filter(([k]) => k === key)
    .map(([, v]) => v.replace(/^`|`$/g, ''))
    .filter((v) => v !== 'none');
}

// plank-join: join every plank to a current step-definition pattern, and redden where the
// join fails. Scans the `implementation` paths for @planks and @planks-provisional tokens,
// the `verification` paths for step-definition patterns, and the `specs` paths for the
// @captain scenarios a provisional plank may name.
//
// Weakness, named at fitting out: the annotation scan is regex over source text with a
// docblock-context test, not a full AST-with-comments reader. It can misjudge a plank token
// inside a string literal. A parser-backed reader would close that gap.
import { readdirSync, readFileSync, statSync } from 'node:fs';
import path from 'node:path';
import { ROOT, readRigging, values } from './rigging.mjs';

const SOURCE = /\.(mjs|cjs|js)$/;

function walk(dir, out = []) {
  let entries;
  try {
    entries = readdirSync(dir);
  } catch {
    return out;
  }
  for (const entry of entries) {
    if (entry === 'node_modules' || entry.startsWith('.')) continue;
    const full = path.join(dir, entry);
    if (statSync(full).isDirectory()) walk(full, out);
    else out.push(full);
  }
  return out;
}

function filesUnder(paths, filter) {
  const out = [];
  for (const p of paths) for (const f of walk(path.join(ROOT, p))) if (filter.test(f)) out.push(f);
  return out;
}

const rigging = readRigging();
const implementation = values(rigging, 'Directories', 'implementation');
const verification = values(rigging, 'Directories', 'verification');
const specs = values(rigging, 'Directories', 'specs');

// Step-definition patterns, exactly as the definitions declare them.
const patterns = new Set();
for (const file of filesUnder(verification, SOURCE)) {
  const src = readFileSync(file, 'utf8');
  for (const m of src.matchAll(/\b(?:Given|When|Then)\s*\(\s*(['"`])([\s\S]*?)\1/g)) {
    patterns.add(m[2]);
  }
}

// @captain scenarios, in repo-root-relative reference form.
const captainScenarios = new Set();
for (const file of filesUnder(specs, /\.feature$/)) {
  const rel = path.relative(ROOT, file);
  const lines = readFileSync(file, 'utf8').split('\n');
  for (let i = 0; i < lines.length; i += 1) {
    if (!/^\s*@/.test(lines[i]) || !/(^|\s)@captain(\s|$)/.test(lines[i])) continue;
    const next = lines[i + 1] || '';
    const name = next.match(/^\s*Scenario(?: Outline)?:\s*(.+?)\s*$/);
    if (name) captainScenarios.add(`${rel}:${name[1]}`);
  }
}

// Plank annotations on production seams.
const faults = [];
const join = [];
let seams = 0;

for (const file of filesUnder(implementation, SOURCE)) {
  const rel = path.relative(ROOT, file);
  const src = readFileSync(file, 'utf8');
  const lines = src.split('\n');
  const docblockLines = new Set();
  let inBlock = false;
  for (let i = 0; i < lines.length; i += 1) {
    if (/^\s*\/\*\*/.test(lines[i])) inBlock = true;
    if (inBlock) docblockLines.add(i);
    if (/\*\//.test(lines[i])) inBlock = false;
  }
  for (let i = 0; i < lines.length; i += 1) {
    const tokens = [...lines[i].matchAll(/@planks(-provisional)?\s*\(\s*(['"])([\s\S]*?)\2\s*\)/g)];
    const bare = /@planks(-provisional)?\b/.test(lines[i]) && tokens.length === 0;
    if (bare) {
      faults.push(`${rel}:${i + 1}: malformed plank token, no quoted reference`);
      continue;
    }
    for (const token of tokens) {
      const provisional = Boolean(token[1]);
      const value = token[3];
      if (!docblockLines.has(i)) {
        faults.push(`${rel}:${i + 1}: plank outside a docblock: ${value}`);
        continue;
      }
      // The docblock must immediately precede a declaration.
      let j = i;
      while (j < lines.length && !/\*\//.test(lines[j])) j += 1;
      let k = j + 1;
      while (k < lines.length && lines[k].trim() === '') k += 1;
      const declaration = (lines[k] || '').trim();
      if (!/[A-Za-z_$]/.test(declaration)) {
        faults.push(`${rel}:${i + 1}: plank docblock precedes no declaration: ${value}`);
        continue;
      }
      seams += 1;
      if (provisional) {
        if (!captainScenarios.has(value)) {
          faults.push(`${rel}:${i + 1}: provisional plank names no @captain scenario: ${value}`);
        } else {
          join.push(`${rel} -> @captain ${value}`);
        }
      } else if (!patterns.has(value)) {
        faults.push(`${rel}:${i + 1}: plank matches no current step-definition pattern: ${value}`);
      } else {
        join.push(`${rel} -> ${value}`);
      }
    }
  }
}

// A behaviour-bearing step-definition pattern with no plank carrying it.
const planked = new Set(join.map((line) => line.split(' -> ')[1]));
const orphans = [...patterns].filter((p) => !planked.has(p));

console.log(`step-definition patterns: ${patterns.size}`);
console.log(`planked seams: ${seams}`);
console.log(`@captain scenarios: ${captainScenarios.size}`);
for (const line of join) console.log(`join ${line}`);
for (const p of orphans) console.log(`unplanked pattern: ${p}`);
for (const fault of faults) console.log(`fault ${fault}`);

if (faults.length > 0) {
  console.error(`plank-join: ${faults.length} fault(s)`);
  process.exit(1);
}
console.log('plank-join: clean');

