  "$schema": "https://shipshape.invalid/verification-conformance/v1",
  "description": "Static rules over verification support. Each rule reddens a Verification-agreement breach. Text-pattern rules: the stack carries no policy engine for verification support, so matches are line-based and a match inside a comment or string is a known false-positive class.",
  "exemptionMarker": "@exceptional-double",
  "rules": [
    {
      "id": "no-guessed-delay",
      "pattern": "setTimeout\\s*\\(\\s*(?:\\(\\s*\\)|[A-Za-z_$][\\w$]*)?\\s*(?:=>|function)",
      "message": "Guessed delay in verification support. End a wait on an observed signal, or retry in bounded intervals toward a deadline."
    },
    {
      "id": "no-sleep-helper",
      "pattern": "\\b(sleep|delay|wait)\\s*\\(\\s*\\d+\\s*\\)",
      "message": "Fixed-duration wait in verification support. Wait on a signal, not on a clock."
    },
    {
      "id": "no-unmarked-double",
      "pattern": "\\b(sinon|jest\\.mock|createMock|makeStub|stubbed|fakeStorage)\\b",
      "message": "Test double in verification support with no inline @exceptional-double mark naming its condition."
    },
    {
      "id": "no-hand-built-dom",
      "pattern": "createElement\\s*\\(\\s*['\"]section['\"]",
      "message": "Verification support building app markup by hand. Load the real index.html instead."
    },
    {
      "id": "no-skipped-scenario",
      "pattern": "\\b(xit|it\\.skip|describe\\.skip|pending\\s*\\(\\s*\\))\\b",
      "message": "Skipped verification is unverified."
    }
  ]
}

// Verification-conformance check: apply the rule set under `scantlings` to the verification
// support paths. A line carrying the rule set's exemption marker, or the line above it, is
// exempt. Text-pattern rules; the weakness is recorded in the rule set itself.
import { readdirSync, readFileSync, statSync } from 'node:fs';
import path from 'node:path';
import { ROOT, readRigging, values } from './rigging.mjs';

function walk(dir, out = []) {
  let entries;
  try {
    entries = readdirSync(dir);
  } catch {
    return out;
  }
  for (const entry of entries) {
    if (entry === 'node_modules' || entry.startsWith('.')) continue;
    const full = path.join(dir, entry);
    if (statSync(full).isDirectory()) walk(full, out);
    else if (/\.(mjs|cjs|js)$/.test(full)) out.push(full);
  }
  return out;
}

const rigging = readRigging();
const ruleSets = values(rigging, 'Directories', 'scantlings');
const verification = values(rigging, 'Directories', 'verification');

const rules = [];
for (const rel of ruleSets) {
  const doc = JSON.parse(readFileSync(path.join(ROOT, rel), 'utf8'));
  if (!Array.isArray(doc.rules)) continue;
  for (const rule of doc.rules) rules.push({ ...rule, marker: doc.exemptionMarker });
}

const breaches = [];
for (const dir of verification) {
  for (const file of walk(path.join(ROOT, dir))) {
    const rel = path.relative(ROOT, file);
    const lines = readFileSync(file, 'utf8').split('\n');
    for (let i = 0; i < lines.length; i += 1) {
      const exempt =
        (rules[0]?.marker && lines[i].includes(rules[0].marker)) ||
        (rules[0]?.marker && (lines[i - 1] || '').includes(rules[0].marker));
      if (exempt) continue;
      for (const rule of rules) {
        if (new RegExp(rule.pattern).test(lines[i])) {
          breaches.push(`${rel}:${i + 1}: ${rule.id}: ${rule.message}`);
        }
      }
    }
  }
}

console.log(`conformance rules: ${rules.length}`);
console.log(`verification files scanned under: ${verification.join(', ') || 'none'}`);
for (const breach of breaches) console.log(`breach ${breach}`);

if (breaches.length > 0) {
  console.error(`conformance: ${breaches.length} breach(es)`);
  process.exit(1);
}
console.log('conformance: clean');

